static at::Tensor tensor(const std::vector<float>&v,std::vector<int64_t> shape){auto* region=new t0common::Buffer<float>();region->resize(v.size());std::copy(v.begin(),v.end(),region->data());return at::from_blob(region->data(),shape,[region](void*){delete region;},at::TensorOptions().dtype(at::kFloat).device(at::kCPU));}
