static bool report_buffer(const char*fixture,int M,const char*candidate,const char*name,const char*function,const char*alias,const at::Tensor&t){auto p=reinterpret_cast<std::uintptr_t>(t.data_ptr());MEMORY_BASIC_INFORMATION mbi{};VirtualQuery(reinterpret_cast<void*>(p),&mbi,sizeof(mbi));SYSTEM_INFO si{};GetSystemInfo(&si);const uintptr_t page=si.dwPageSize,start=p&~(page-1),end=(p+t.nbytes()+page-1)&~(page-1);std::vector<PSAPI_WORKING_SET_EX_INFORMATION> ws;for(uintptr_t q=start;q<end;q+=page){PSAPI_WORKING_SET_EX_INFORMATION item{};item.VirtualAddress=reinterpret_cast<void*>(q);ws.push_back(item);}BOOL q=!ws.empty()&&QueryWorkingSetEx(GetCurrentProcess(),ws.data(),DWORD(ws.size()*sizeof(ws[0])));size_t large=0,valid=0;if(q)for(const auto& item:ws){large+=item.VirtualAttributes.LargePage!=0;valid+=item.VirtualAttributes.Valid!=0;}std::cout<<"PAGE fixture="<<fixture<<" m="<<M<<" candidate="<<candidate<<" buffer="<<name<<" function="<<function<<" alias="<<alias<<" address=0x"<<std::hex<<p<<std::dec<<" bytes="<<t.nbytes()<<" queried_pages="<<ws.size()<<" valid_pages="<<valid<<" large_pages="<<large<<" QueryWorkingSetEx="<<(q?"PASS":"FAIL")<<" LargePage="<<(large==ws.size()?"true":"false")<<"\n";return q!=FALSE&&!ws.empty()&&valid==ws.size()&&large==ws.size();}
static std::vector<float> unpack_weights(const t0common::Cell&c,bool trans){std::vector<float>v(size_t(t0common::O)*t0common::I);for(int o=0;o<t0common::O;++o)for(int i=0;i<t0common::I;++i)v[trans?size_t(i)*t0common::O+o:size_t(o)*t0common::I+i]=float(c.wq[o*t0common::I+i])*c.ws[o*t0common::G+i/32];return v;}
static at::Tensor common_output(int M,const std::string&name){auto* region=new t0common::Buffer<float>();region->resize(size_t(M)*t0common::O);std::fill(region->begin(),region->end(),0.0f);auto shape=name=="mv"?std::vector<int64_t>{t0common::O}:std::vector<int64_t>{M,t0common::O};return at::from_blob(region->data(),shape,[region](void*){delete region;},at::TensorOptions().dtype(at::kFloat).device(at::kCPU));}
