 if(name=="mkldnn_linear")return at::mkldnn_linear(Xd,Wd,std::optional<at::Tensor>());
 const auto ptr=Y.data_ptr();const auto storage=Y.storage().data_ptr().get();const auto sizes=Y.sizes().vec();const auto strides=Y.strides().vec();const auto bytes=Y.nbytes();
 if(name=="mm")at::mm_out(Y,X,Wt);else if(name=="matmul")at::matmul_out(Y,X,Wt);else if(name=="linear")at::linear_out(Y,X,W,std::optional<at::Tensor>());else if(name=="mv")at::mv_out(Y,W,X[0]);else throw std::runtime_error("unknown candidate");
